import React, { useEffect, useState } from "react";

function Search() {
  const [buses, setBuses] = useState([]);
  const [filteredBuses, setFilteredBuses] = useState([]);
  const [source, setSource] = useState("");
  const [destination, setDestination] = useState("");
  const [loading, setLoading] = useState(true);
  const [searched, setSearched] = useState(false);

  // ✅ Fetch buses from backend
  useEffect(() => {
    fetch("http://localhost:3000/api/buses")
      .then((res) => res.json())
      .then((data) => {
        setBuses(data);
        setFilteredBuses(data);
        setLoading(false);
      })
      .catch((err) => {
        console.log("API Error:", err);
        setLoading(false);
      });
  }, []);

  // ✅ Search logic
  const handleSearch = () => {
    setSearched(true);

    const results = buses.filter(
      (bus) =>
        bus.source.toLowerCase().includes(source.toLowerCase()) &&
        bus.destination.toLowerCase().includes(destination.toLowerCase())
    );

    setFilteredBuses(results);
  };

  // ✅ Reset search
  const handleReset = () => {
    setSource("");
    setDestination("");
    setFilteredBuses(buses);
    setSearched(false);
  };

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-3xl font-bold text-center mb-6">
        🚌 Bus Schedules
      </h1>

      {/* Search Box */}
      <div className="bg-white shadow-md rounded-lg p-4 mb-6">
        <div className="flex gap-4">
          <input
            type="text"
            placeholder="Source"
            value={source}
            onChange={(e) => setSource(e.target.value)}
            className="border p-2 rounded w-full"
          />

          <input
            type="text"
            placeholder="Destination"
            value={destination}
            onChange={(e) => setDestination(e.target.value)}
            className="border p-2 rounded w-full"
          />
        </div>

        <div className="flex gap-4 mt-3">
          <button
            onClick={handleSearch}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded w-full"
          >
            🔍 Search
          </button>

          <button
            onClick={handleReset}
            className="bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded w-full"
          >
            Reset
          </button>
        </div>
      </div>

      {/* Loading */}
      {loading ? (
        <p className="text-center text-gray-500">Loading buses...</p>
      ) : (
        <>
          {/* Bus List */}
          {filteredBuses.length > 0 ? (
            <div className="space-y-4">
              {filteredBuses.map((bus) => (
                <div
                  key={bus._id}
                  className="border p-4 rounded-lg shadow bg-gray-50"
                >
                  <h2 className="text-xl font-bold">{bus.name}</h2>

                  <p>
                    🚏 {bus.source} → {bus.destination}
                  </p>

                  <p>🕒 {bus.time}</p>

                  <p className="text-green-600 font-semibold">
                    💰 ₹{bus.fare}
                  </p>
                </div>
              ))}
            </div>
          ) : searched ? (
            <p className="text-center text-gray-500">
              ❌ No buses found for this route
            </p>
          ) : (
            <p className="text-center text-gray-500">
              Enter route details to search buses
            </p>
          )}
        </>
      )}
    </div>
  );
}

export default Search;
